import{Z as t,e as a,f as n,a0 as o}from"./chunks/framework.DmpHOl9T.js";const g=JSON.parse('{"title":"CleanTalk","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/captchas/cleantalk.md","filePath":"integrations/captchas/cleantalk.md","lastUpdated":1781527112000}'),s={name:"integrations/captchas/cleantalk.md"};function i(r,e,l,c,h,p){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="cleantalk" tabindex="-1">CleanTalk <a class="header-anchor" href="#cleantalk" aria-label="Permalink to &quot;CleanTalk&quot;">​</a></h1><p>Follow the below steps to connect Formie to the CleanTalk API.</p><h3 id="step-1-open-the-captcha-settings" tabindex="-1">Step 1. Open the Captcha Settings <a class="header-anchor" href="#step-1-open-the-captcha-settings" aria-label="Permalink to &quot;Step 1. Open the Captcha Settings&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Spam Protection</strong> → <strong>Captchas</strong>.</li><li>Select <strong>CleanTalk</strong> in the left-hand sidebar.</li><li>Turn on <strong>Enabled</strong>.</li></ol><h3 id="step-2-get-your-cleantalk-access-key" tabindex="-1">Step 2. Get Your CleanTalk Access Key <a class="header-anchor" href="#step-2-get-your-cleantalk-access-key" aria-label="Permalink to &quot;Step 2. Get Your CleanTalk Access Key&quot;">​</a></h3><ol><li>Go to <a href="https://cleantalk.org/" target="_blank" rel="noreferrer">CleanTalk</a> and create an account, or sign in to an existing one.</li><li>Add your website in the CleanTalk dashboard if prompted.</li><li>Open your CleanTalk Control Panel at <code>https://cleantalk.org/my</code>.</li><li>Copy your <strong>Access key</strong>. In Formie this is entered as the <strong>API Key</strong>.</li></ol><h3 id="step-3-connect-formie-to-cleantalk" tabindex="-1">Step 3. Connect Formie to CleanTalk <a class="header-anchor" href="#step-3-connect-formie-to-cleantalk" aria-label="Permalink to &quot;Step 3. Connect Formie to CleanTalk&quot;">​</a></h3><ol><li>Paste the access key into the <strong>API Key</strong> field in Formie.</li><li>Save the captcha settings.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to protect.</li><li>Enable <strong>CleanTalk</strong> for that form.</li><li>For multi-page forms, turn on <strong>Show on All Pages</strong> if the spam check should run on every page instead of only the final submit step.</li><li>Save the form.</li></ol><p>CleanTalk screens submissions in the background, so there is no visible challenge on the front end.</p><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Submit through the site and check the resulting submission and spam state. A saved credential alone does not verify the visitor-facing challenge or server-side check.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',14)])])}const m=t(s,[["render",i]]);export{g as __pageData,m as default};
